mapper.select:
SELECT id, title, description, category, impact_scope, urgency, status, priority, priority_reason, creator_id, handler_id, overdue, escalation_level, create_time, update_time, close_time, deadline_time FROM ticket
WHERE 1 = 1
AND status = #{status}
AND priority = #{priority}
AND creator_id = #{creatorId}
AND handler_id = #{handlerId}
AND ( title LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY create_time DESC

mapper.update:
UPDATE ticket
SET priority = #{priority}
WHERE id = #{ticketId}

UPDATE ticket
SET handler_id = #{handlerId},
status = 'PROCESSING',
update_time = NOW()
WHERE id = #{ticketId}
AND status = #{expectedStatus}
